diff --git a/cmd/entire/cli/checkpoint_backend.go b/cmd/entire/cli/checkpoint_backend.go
index 7b9cb232..5db74218 100644
--- a/cmd/entire/cli/checkpoint_backend.go
+++ b/cmd/entire/cli/checkpoint_backend.go
@@ -2,6 +2,7 @@ package cli

 import (
 	"context"
+	"errors"
 	"fmt"
 	"io"
 	"slices"
@@ -98,7 +99,10 @@ func checkpointBackendChoices() (opts []huh.Option[string], recommended string)
 // an interactive terminal (and skip it when ENTIRE_CHECKPOINTS_PRIMARY is
 // active — the env fully replaces settings, so an answer could not take
 // effect and would only write diverging config).
-func promptCheckpointBackend(ctx context.Context, w io.Writer) (string, error) {
+//
+// Package-level var so tests can substitute it — the real prompt needs a TTY
+// that `go test` doesn't have.
+var promptCheckpointBackend = func(ctx context.Context, w io.Writer) (string, error) {
 	opts, recommended := checkpointBackendChoices()
 	choice := recommended
 	form := NewAccessibleForm(
@@ -111,11 +115,27 @@ func promptCheckpointBackend(ctx context.Context, w io.Writer) (string, error) {
 		),
 	)
 	if err := form.RunWithContext(ctx); err != nil {
+		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
+			// Cancelling the storage question cancels `entire enable`; it must
+			// not silently adopt a default and march on to later prompts. No
+			// settings are persisted until after this prompt, so re-running
+			// `entire enable` resumes here. Deliberately NOT a soft
+			// handleFormCancellation skip like the optional prompts elsewhere.
+			return "", errSetupCancelled
+		}
 		return "", handleFormCancellation(w, "Checkpoint storage selection", err)
 	}
 	return choice, nil
 }

+// errSetupCancelled marks a first-run setup prompt the user cancelled (Ctrl+C).
+// It propagates up through runEnableInteractive so `entire enable` stops
+// instead of persisting a default and continuing; runSetupFlow turns it into a
+// friendly "run enable again to resume" line and a SilentError so the process
+// exits cleanly. Because no settings are written until after the storage
+// prompt, the next `entire enable` is still a fresh run and lands back here.
+var errSetupCancelled = errors.New("setup cancelled")
+
 // updateCheckpointBackend persists opts.CheckpointBackend to the target settings
 // file. Used by `entire configure` and by `entire enable` on repos that are
 // already set up (both operate on an on-disk file rather than the in-memory
diff --git a/cmd/entire/cli/corecmd.go b/cmd/entire/cli/corecmd.go
index 96bc33f3..a50e170b 100644
--- a/cmd/entire/cli/corecmd.go
+++ b/cmd/entire/cli/corecmd.go
@@ -7,6 +7,7 @@ import (
 	"errors"
 	"fmt"
 	"io"
+	"regexp"
 	"strconv"
 	"strings"

@@ -636,6 +637,12 @@ func markRequired(cmd *cobra.Command, names ...string) {
 // SilenceUsage, so the message reaches the user without a usage dump. (A
 // SilentError here would be swallowed — main.go skips printing those —
 // leaving e.g. a 409 conflict with no output.)
+// coreErrorStatusRe extracts the HTTP status from ogen's generated decoder
+// wrapping ("default (code 502)"), the only place the status survives when a
+// response fails to decode — e.g. a gateway 502 serving a text/plain error
+// page — since no typed error exists on that path.
+var coreErrorStatusRe = regexp.MustCompile(`\(code (\d{3})\)`)
+
 func renderCoreError(err error) error {
 	if err == nil {
 		return nil
@@ -643,6 +650,15 @@ func renderCoreError(err error) error {
 	if msg := coreapi.APIError(err); msg != "" {
 		return errors.New(msg)
 	}
+	// A response that failed decoding renders as ogen's raw wrap chain
+	// ("decode response: … unexpected Content-Type: text/plain") — developer
+	// noise where a user needs one line. Collapse it to the status.
+	if m := coreErrorStatusRe.FindStringSubmatch(err.Error()); m != nil {
+		if m[1][0] == '5' {
+			return fmt.Errorf("the control plane returned HTTP %s — try again shortly", m[1])
+		}
+		return fmt.Errorf("control-plane request failed with HTTP %s", m[1])
+	}
 	return err
 }

